use crate::model::ModelError;

/// A sound for the end of a brew: one of the long sounds the app ships
/// (`assets/sounds/<id>.mp3`, generated by `scripts/gen-sounds.py`). Where
/// a step sound is one cue of many, these mark the only end: each rings
/// out and resolves, over 2.4–4.6 s. A closed set.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FinishSound {
    SingingBowl,
    BowlTwice,
    BowlCadence,
    KalimbaCadence,
    KalimbaRise,
    TingshaThree,
    CounterBell,
    WindChimes,
    LastDrops,
    Gong,
    SpoonOnCup,
    MusicBox,
}

impl FinishSound {
    /// Every finish sound, in the picker's order.
    pub const ALL: [Self; 12] = [
        Self::SingingBowl,
        Self::BowlTwice,
        Self::BowlCadence,
        Self::KalimbaCadence,
        Self::KalimbaRise,
        Self::TingshaThree,
        Self::CounterBell,
        Self::WindChimes,
        Self::LastDrops,
        Self::Gong,
        Self::SpoonOnCup,
        Self::MusicBox,
    ];

    /// Before one is chosen: the long bowl.
    pub const DEFAULT: Self = Self::SingingBowl;

    /// The id: the asset's file stem and the string persisted in storage.
    pub fn id(self) -> &'static str {
        match self {
            Self::SingingBowl => "singing-bowl",
            Self::BowlTwice => "bowl-twice",
            Self::BowlCadence => "bowl-cadence",
            Self::KalimbaCadence => "kalimba-cadence",
            Self::KalimbaRise => "kalimba-rise",
            Self::TingshaThree => "tingsha-three",
            Self::CounterBell => "counter-bell",
            Self::WindChimes => "wind-chimes",
            Self::LastDrops => "last-drops",
            Self::Gong => "gong",
            Self::SpoonOnCup => "spoon-on-cup",
            Self::MusicBox => "music-box",
        }
    }

    /// The picker's name: `Bowl struck twice`.
    pub fn label(self) -> &'static str {
        match self {
            Self::SingingBowl => "Singing bowl",
            Self::BowlTwice => "Bowl struck twice",
            Self::BowlCadence => "Bowl cadence",
            Self::KalimbaCadence => "Kalimba cadence",
            Self::KalimbaRise => "Kalimba rise",
            Self::TingshaThree => "Tingsha three times",
            Self::CounterBell => "Counter bell",
            Self::WindChimes => "Wind chimes",
            Self::LastDrops => "Last drops",
            Self::Gong => "Gong",
            Self::SpoonOnCup => "Spoon on cup",
            Self::MusicBox => "Music box",
        }
    }

    /// How long the asset plays, in ms.
    pub fn duration_ms(self) -> u32 {
        match self {
            Self::SingingBowl => 3000,
            Self::BowlTwice | Self::BowlCadence => 4600,
            Self::KalimbaCadence | Self::KalimbaRise => 2600,
            Self::TingshaThree => 3800,
            Self::CounterBell => 3400,
            Self::WindChimes => 4000,
            Self::LastDrops => 2400,
            Self::Gong => 4400,
            Self::SpoonOnCup => 3200,
            Self::MusicBox => 3900,
        }
    }

    /// Parses a [`FinishSound::id`] strictly: anything else, a step sound
    /// included, is [`ModelError::UnknownFinishSound`].
    pub fn try_parse(raw: &str) -> Result<Self, ModelError> {
        Self::ALL
            .into_iter()
            .find(|sound| sound.id() == raw)
            .ok_or_else(|| ModelError::UnknownFinishSound(raw.to_owned()))
    }
}
